<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
require __DIR__.'/heatmap_lib.php';
require __DIR__.'/cook_activity_lib.php';
$uid=auth();$error='';$h=static fn($x):string=>htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$days=in_array((int)($_GET['days']??7),[1,7,30],true)?(int)($_GET['days']??7):7;
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();
 try {
  $action=(string)($_POST['action']??'');
  if($action==='assign'){
   $ovenId=(int)($_POST['oven_id']??0);$evidenceId=(int)($_POST['evidence_id']??0);
   if($ovenId<1||!query('SELECT id FROM oven_layouts WHERE id=?',[$ovenId])->fetchColumn())throw new RuntimeException('Choose a saved oven layout.');
   if($evidenceId<1||!query('SELECT id FROM evidence WHERE id=?',[$evidenceId])->fetchColumn())throw new RuntimeException('Select a real pizza evidence record.');
   $already=query('SELECT s.id,s.oven_layout_id FROM oven_cook_sessions s WHERE s.evidence_id=?',[$evidenceId])->fetch();
   if($already){if((int)$already['oven_layout_id']!==$ovenId)throw new RuntimeException('This pizza is already assigned to another oven.');$id=(int)$already['id'];}
   else {query('INSERT INTO oven_cook_sessions (oven_layout_id,evidence_id,notes,created_by_user_id) VALUES (?,?,?,?)',[$ovenId,$evidenceId,plain($_POST['notes']??'',1000),$uid]);$id=(int)db()->lastInsertId();}
   header('Location: heatmap.php?oven_id='.$ovenId.'&session_id='.$id.'&assigned=1');exit;
  }
  if($action==='event'){
   $sid=(int)($_POST['session_id']??0);$s=query('SELECT s.*,o.zones_json FROM oven_cook_sessions s JOIN oven_layouts o ON o.id=s.oven_layout_id WHERE s.id=?',[$sid])->fetch();if(!$s)throw new RuntimeException('Unknown cooking session.');
   $zones=lab_oven_zones(json_decode((string)$s['zones_json'],true,32,JSON_THROW_ON_ERROR));$zoneKey=(string)($_POST['zone_key']??'');$zoneName='Not zoned';$zone=null;
   foreach($zones as $z){if($z['key']===$zoneKey){$zone=$z;$zoneName=$z['name'];break;}}
   if($zoneKey!=='' && !$zone)throw new RuntimeException('Temperature zone no longer exists; choose another.');
   $x=$_POST['x_norm']??null;$y=$_POST['y_norm']??null;
   if(!is_numeric($x)||!is_numeric($y))throw new RuntimeException('Select an oven position.');
   $event=lab_heatmap_event((string)($_POST['phase']??''),$_POST['elapsed_seconds']??null,$_POST['stone_f']??null,(float)$x,(float)$y);
   if($zone){
    $oven=query('SELECT east_west_in,north_south_in FROM oven_layouts WHERE id=?',[$s['oven_layout_id']])->fetch();
    $dist=hypot(($event['x']-$zone['x'])*(float)$oven['east_west_in'],($event['y']-$zone['y'])*(float)$oven['north_south_in']);
    if($dist > (float)$zone['radius_in']+1.5)throw new RuntimeException('Chosen position is outside the selected zone. Choose another zone or leave it unassigned.');
   }
   query('INSERT INTO oven_cook_events (session_id,phase,zone_key,zone_name,x_norm,y_norm,elapsed_seconds,stone_f,notes,observed_at,recorded_by_user_id) VALUES (?,?,?,?,?,?,?,?,?,NOW(),?)',[$sid,$event['phase'],$zoneKey,$zoneName,$event['x'],$event['y'],$event['elapsed_seconds'],$event['stone_f'],plain($_POST['notes']??'',1000),$uid]);
   header('Location: heatmap.php?oven_id='.$s['oven_layout_id'].'&session_id='.$sid.'&logged=1');exit;
  }
  throw new RuntimeException('Unsupported action.');
 }catch(Throwable $e){$error=$e->getMessage();}
}
$ovens=query('SELECT id,name FROM oven_layouts ORDER BY updated_at DESC,id DESC LIMIT 60')->fetchAll();$ovenId=(int)($_GET['oven_id']??($ovens[0]['id']??0));
$oven=$ovenId?query('SELECT * FROM oven_layouts WHERE id=?',[$ovenId])->fetch():null;
if(!$oven)$ovenId=0;
$zones=$oven?lab_oven_zones(json_decode((string)$oven['zones_json'],true,32,JSON_THROW_ON_ERROR)):[];
$sessions=$oven?query('SELECT s.id,s.evidence_id,e.label,e.crispness_score,e.bottom_color_score,e.rim_rise_score,s.created_at FROM oven_cook_sessions s JOIN evidence e ON e.id=s.evidence_id WHERE s.oven_layout_id=? ORDER BY s.id DESC LIMIT 150',[$ovenId])->fetchAll():[];
$selected=(int)($_GET['session_id']??($sessions[0]['id']??0));$chosen=null;foreach($sessions as $s){if((int)$s['id']===$selected){$chosen=$s;break;}}if(!$chosen)$selected=0;
$trajectory=$selected?query('SELECT ce.*,u.display_name FROM oven_cook_events ce JOIN users u ON u.id=ce.recorded_by_user_id WHERE ce.session_id=? ORDER BY COALESCE(ce.elapsed_seconds,2147483647),ce.id LIMIT 120',[$selected])->fetchAll():[];
$readings=$oven?query('SELECT zone_key,stone_f,observed_at FROM oven_zone_readings WHERE oven_layout_id=? AND observed_at>=DATE_SUB(NOW(), INTERVAL ? DAY) ORDER BY observed_at DESC,id DESC LIMIT 1500',[$ovenId,$days])->fetchAll():[];
$cookRows=$oven?query('SELECT ce.id,ce.session_id,ce.zone_key,ce.phase,ce.stone_f,ce.elapsed_seconds,ce.observed_at,e.id evidence_id,e.crispness_score,e.bottom_color_score,e.rim_rise_score FROM oven_cook_events ce JOIN oven_cook_sessions s ON s.id=ce.session_id JOIN evidence e ON e.id=s.evidence_id WHERE s.oven_layout_id=? AND ce.observed_at>=DATE_SUB(NOW(), INTERVAL ? DAY) ORDER BY ce.observed_at DESC,ce.id DESC LIMIT 1500',[$ovenId,$days])->fetchAll():[];
$metrics=lab_heatmap_summary($zones,$readings,$cookRows);
$unassigned=$oven?query('SELECT e.id,e.label,b.batch_code FROM evidence e LEFT JOIN dough_batches b ON b.id=e.batch_id WHERE NOT EXISTS (SELECT 1 FROM oven_cook_sessions s WHERE s.evidence_id=e.id) ORDER BY e.created_at DESC,e.id DESC LIMIT 100')->fetchAll():[];
$activity=$chosen?query('SELECT a.*,u.display_name chef FROM oven_cook_activity a JOIN users u ON u.id=a.created_by_user_id WHERE a.evidence_id=? ORDER BY a.id DESC LIMIT 120',[(int)$chosen['evidence_id']])->fetchAll():[];
$fmt=static fn($n):string=>$n===null?'Not recorded':number_format((float)$n,1);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Oven Heat Map · Pizza Lab</title><link rel="stylesheet" href="assets/style.css?v=1.5.7"><style>.heatmap-svg{width:100%;max-height:580px;background:#111923;border:1px solid #37454e;border-radius:12px;touch-action:manipulation}.heatmap-svg text{fill:#f5e7d6;font-size:12px}.heatmap-svg .spot{cursor:pointer;stroke:#f4e6cd;stroke-width:2}.heatmap-table{width:100%;border-collapse:collapse}.heatmap-table td,.heatmap-table th{padding:8px;border-bottom:1px solid #4449;text-align:left}.heatmap-options{display:flex;gap:12px;flex-wrap:wrap}.heatmap-options label{flex:1;min-width:145px}.heatmap-muted{font-size:.85rem;color:var(--muted)}.heatmap-steps{max-height:330px;overflow:auto}</style></head><body><main class="view" style="max-width:1380px"><p><a href="index.php">← Pizza Lab</a> · <a href="oven_layout.php">Edit oven floor</a> · <a href="agent_chat.php">Agent Chat</a></p><h1>Cooking Performance Heat Map</h1><p>Overlay actual infrared stone readings and recorded pizza positions on your oven floor. No temperature interpolation or thermal-camera claims. Pizza outcomes are associated with all zones visited, <strong>not attributed causally</strong> to any one zone.</p><?php if($error):?><p class="danger"><?=$h($error)?></p><?php endif;?><?php if(isset($_GET['assigned'])||isset($_GET['logged'])):?><p class="notice-strip">Cooking evidence saved.</p><?php endif;?><form method="get" class="flex panel"><label>Oven layout<select name="oven_id" onchange="this.form.submit()"><option value="">Choose oven</option><?php foreach($ovens as $o):?><option value="<?=$o['id']?>" <?=$ovenId===(int)$o['id']?'selected':''?>><?=$h($o['name'])?></option><?php endforeach;?></select></label><label>Review window<select name="days" onchange="this.form.submit()"><option value="1" <?=$days===1?'selected':''?>>24 hours</option><option value="7" <?=$days===7?'selected':''?>>7 days</option><option value="30" <?=$days===30?'selected':''?>>30 days</option></select></label><button>Apply</button></form>
<?php if(!$oven):?><section class="panel"><h2>No oven layout yet</h2><p>Set up the oven floor, fire location and zones first.</p><p><a href="oven_layout.php">Create an oven layout →</a></p></section><?php else:?>
<div class="grid-2 mt"><section class="panel stack"><h2><?=$h($oven['name'])?> · floor overview</h2><div class="heatmap-options"><label>Display metric<select id="metric"><option value="temp">Latest measured stone °F</option><option value="crisp">Recorded crispness / 10</option><option value="color">Recorded bottom color / 10</option><option value="rise">Recorded oven spring / 10</option></select></label><label>Cooking path<select id="sessionPicker"><option value="">No pizza selected</option><?php foreach($sessions as $s):?><option value="<?=$s['id']?>" <?=$selected===(int)$s['id']?'selected':''?>>#<?=$s['evidence_id']?> · <?=$h($s['label'])?></option><?php endforeach;?></select></label></div><svg id="heatmapCanvas" class="heatmap-svg" viewBox="0 0 660 500" aria-label="Oven floor, measured zones and recorded pizza movement" role="img"><ellipse cx="330" cy="240" rx="275" ry="202" fill="#2a333b" stroke="#99a3a7" stroke-width="3"/><text x="330" y="23" text-anchor="middle">NORTH</text><text x="330" y="489" text-anchor="middle">SOUTH / ENTRANCE</text><text x="15" y="243">W</text><text x="632" y="243">E</text><g id="heatZones"></g><g id="cookingPath"></g></svg><div class="heatmap-muted" id="mapLegend">Dots show actual readings. Gray = no recorded measurement in the selected period.</div><div class="heatmap-muted" id="pickedPosition" aria-live="polite">Click the oven floor to set a cooking position. No event is recorded until you submit the form.</div></section>
<section class="panel stack"><h2>Log a cooking path</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=$h(csrf())?>"><input type="hidden" name="action" value="assign"><input type="hidden" name="oven_id" value="<?=$ovenId?>"><label>Assign pizza test to this oven<select name="evidence_id" required><option value="">Choose unassigned pizza</option><?php foreach($unassigned as $e):?><option value="<?=$e['id']?>">#<?=$e['id']?> · <?=$h($e['label'])?> <?=$h($e['batch_code']??'')?></option><?php endforeach;?></select></label><label>Notes (optional)<input name="notes" maxlength="1000"></label><button>Link pizza to oven</button></form><?php if($selected):?><hr><form method="post" id="cookEventForm" class="stack"><input type="hidden" name="csrf" value="<?=$h(csrf())?>"><input type="hidden" name="action" value="event"><input type="hidden" name="session_id" value="<?=$selected?>"><input type="hidden" id="posX" name="x_norm" value=".5"><input type="hidden" id="posY" name="y_norm" value=".5"><label>Pizza test<strong> #<?=$chosen['evidence_id']?> · <?=$h($chosen['label'])?></strong></label><div class="heatmap-options"><label>Cooking event<select name="phase" required><option value="launch">Launch</option><option value="initial_puff">Initial puff</option><option value="pull_back">Pull back</option><option value="rotate">Rotate</option><option value="finish">Finish</option><option value="check">Position check</option></select></label><label>Temperature zone<select name="zone_key" id="eventZone"><option value="">Outside named zones</option><?php foreach($zones as $z):?><option value="<?=$h($z['key'])?>"><?=$h($z['name'])?></option><?php endforeach;?></select></label></div><div class="heatmap-options"><label>Elapsed seconds (optional)<input type="number" min="0" max="7200" name="elapsed_seconds" placeholder="e.g. 75"></label><label>IR stone °F (optional)<input type="number" min="0" max="1500" step=".1" name="stone_f" placeholder="Actual reading only"></label></div><label>Notes (optional)<input name="notes" maxlength="1000" placeholder="e.g. first puff, right rim browning"></label><button class="primary">Record event at selected position</button></form><?php else:?><p class="heatmap-muted">Link an existing pizza test to this oven to start recording its positions and cooking events.</p><?php endif;?></section></div>
<section class="panel mt"><h2>Temperature zones and recorded performance</h2><p class="heatmap-muted">Ratings count distinct pizzas with at least one cooking event in a zone. A pizza visiting multiple zones contributes to each visited zone; averages are observational and can be confounded by recipe, dough age and toppings. Missing ratings remain unknown.</p><div style="overflow-x:auto"><table class="heatmap-table"><thead><tr><th>Zone</th><th>Latest actual °F</th><th>IR readings</th><th>Distinct pizzas</th><th>Crispness</th><th>Bottom color</th><th>Rim rise</th></tr></thead><tbody><?php foreach($metrics as $z):?><tr><td><?=$h($z['name'])?></td><td><?=$h($fmt($z['last_stone_f']))?></td><td><?=$z['reading_count']?></td><td><?=$z['pizzas']?></td><td><?=$h($fmt($z['crisp_avg']))?> (n=<?=$z['crisp_n']?>)</td><td><?=$h($fmt($z['color_avg']))?> (n=<?=$z['color_n']?>)</td><td><?=$h($fmt($z['rise_avg']))?> (n=<?=$z['rise_n']?>)</td></tr><?php endforeach;?></tbody></table></div><?php if(!$zones):?><p>Create named temperature zones in the oven floor builder before comparisons are possible.</p><?php endif;?></section>
<?php if($selected):?><section class="panel mt"><h2>Pizza #<?=$chosen['evidence_id']?> — recorded timeline</h2><div class="heatmap-steps"><table class="heatmap-table"><thead><tr><th>Event</th><th>Elapsed</th><th>Zone at recording</th><th>Stone °F</th><th>Note</th></tr></thead><tbody><?php foreach($trajectory as $t):?><tr><td><?=$h(str_replace('_',' ',$t['phase']))?></td><td><?=$t['elapsed_seconds']===null?'Not recorded':$h($t['elapsed_seconds']).'s'?></td><td><?=$h($t['zone_name'])?></td><td><?=$h($fmt($t['stone_f']))?></td><td><?=$h($t['notes'])?></td></tr><?php endforeach;?></tbody></table></div><p class="heatmap-muted">Other voice-timer and scanner observations remain attached to this pizza evidence record. Event positions and actual IR measurements are entered by a person, not determined from the camera.</p></section><?php endif;?>
<?php if($selected):?><section class="panel mt"><h2>Automatic cooking activity · this pizza</h2><p class="heatmap-muted">Timer reminders, photo captures and AI suggestions are not proof a chef moved the pizza. Only explicitly confirmed actions are marked confirmed. Recorded positions remain in the cooking path above.</p><div class="heatmap-steps"><table class="heatmap-table"><thead><tr><th>When</th><th>Event</th><th>Elapsed</th><th>Class</th><th>Source</th></tr></thead><tbody><?php foreach($activity as $a):?><tr><td><?=$h($a['occurred_at'])?></td><td><?=$h(lab_cook_label($a['event_type']))?></td><td><?=$a['elapsed_seconds']===null?'—':$h($a['elapsed_seconds']).'s'?></td><td><?=$h($a['event_class'])?></td><td><?=$h($a['chef']).' · '.$h($a['source'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<?php endif;?></main><?php if($oven):?><script>window.OVEN_HEATMAP=<?=json_encode(['zones'=>$metrics,'fire'=>['x'=>(float)$oven['fire_x'],'y'=>(float)$oven['fire_y']],'ns'=>(float)$oven['north_south_in'],'ew'=>(float)$oven['east_west_in'],'trajectory'=>$trajectory,'selectedSession'=>$selected],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_INVALID_UTF8_SUBSTITUTE)?>;</script><script src="assets/heatmap.js?v=1.5.7" defer></script><?php endif;?></body></html>
